"use client";

import {
    Search,
    Filter,
    MoreHorizontal,
    FileText,
    Clock,
    CheckCircle2,
    XCircle,
    Calendar,
    User,
    Plus,
    ArrowUpDown,
    Archive,
    FileEdit
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { useSimulation } from "@/components/SimulationProvider";
import useSWR, { mutate } from "swr";
import { fetcher } from "@/lib/fetcher";
import OrderJourneyModal from "@/components/OrderJourneyModal";
import OrderDetailsModal from "@/components/OrderDetailsModal";
import axios from "axios";

const STATUS_CONFIG: Record<string, { icon: any; label: string; className: string }> = {
    Pago: {
        icon: CheckCircle2,
        label: "Pago",
        className: "bg-emerald-50 text-emerald-700 ring-emerald-600/20 dark:bg-emerald-400/10 dark:text-emerald-400 dark:ring-emerald-400/20",
    },
    Pendente: {
        icon: Clock,
        label: "Pendente",
        className: "bg-amber-50 text-amber-700 ring-amber-600/20 dark:bg-amber-400/10 dark:text-amber-400 dark:ring-amber-400/20",
    },
    Cancelado: {
        icon: XCircle,
        label: "Cancelado",
        className: "bg-rose-50 text-rose-700 ring-rose-600/20 dark:bg-rose-400/10 dark:text-rose-400 dark:ring-rose-400/20",
    },
    Rascunho: {
        icon: FileText,
        label: "Rascunho",
        className: "bg-indigo-50 text-indigo-700 ring-indigo-600/20 dark:bg-indigo-400/10 dark:text-indigo-400 dark:ring-indigo-400/20",
    },
    Arquivado: {
        icon: Search,
        label: "Arquivado",
        className: "bg-slate-100 text-slate-700 ring-slate-600/20 dark:bg-slate-700 dark:text-slate-400 dark:ring-slate-500/20",
    },
};

const STATUSES = ["Todos", "Pago", "Pendente", "Cancelado", "Rascunho", "Arquivado"];

export default function CertificatesPage() {
    const { currentUser } = useSimulation();
    const { data: certificates, error } = useSWR(
        `/api/certificates?seller=${currentUser.role === "admin" ? "admin" : currentUser.name}`,
        fetcher
    );
    const { data: products } = useSWR("/api/sales", fetcher);

    const [searchTerm, setSearchTerm] = useState("");
    const [statusFilter, setStatusFilter] = useState("Todos");
    const [showArchived, setShowArchived] = useState(false);
    const [isJourneyOpen, setIsJourneyOpen] = useState(false);
    const [isDetailsOpen, setIsDetailsOpen] = useState(false);
    const [selectedOrder, setSelectedOrder] = useState<any>(null);

    const filteredCertificates = (certificates || []).filter((cert: any) => {
        const matchesSearch =
            cert.holder.toLowerCase().includes(searchTerm.toLowerCase()) ||
            cert.doc.includes(searchTerm) ||
            cert.protocol.toLowerCase().includes(searchTerm.toLowerCase());

        // Logical filter for archived
        const isArchived = cert.status === "Arquivado";
        const matchesArchivedToggle = showArchived ? true : !isArchived;

        const matchesStatus = statusFilter === "Todos"
            ? matchesArchivedToggle
            : cert.status === statusFilter;

        return matchesSearch && matchesStatus;
    });

    const handleArchive = async (id: string) => {
        if (!confirm("Deseja realmente arquivar este rascunho?")) return;
        try {
            const formData = new FormData();
            formData.append('id', id);
            formData.append('status', 'Arquivado');
            formData.append('isUpdateStatusOnly', 'true'); // Flag to prevent data loss

            await axios.post('/api/integracao/vendas', formData);
            mutate(`/api/certificates?seller=${currentUser.role === "admin" ? "admin" : currentUser.name}`);
        } catch (error) {
            alert("Erro ao arquivar.");
        }
    };

    const handleResumeDraft = (cert: any) => {
        setSelectedOrder(cert);
        setIsJourneyOpen(true);
    };

    const handleOrderSubmit = async (data: any) => {
        try {
            const selectedProduct = products.find((p: any) => p.id === data.productId);
            const submissionData = {
                ...data,
                product: selectedProduct?.name,
                category: selectedProduct?.category,
                origin: `Venda Direta - Vendedor ${currentUser.name}`,
            };
            const response = await axios.post("/api/integracao/vendas", submissionData);
            if (response.data.success) {
                setIsJourneyOpen(false);
                mutate(`/api/certificates?seller=${currentUser.role === "admin" ? "admin" : currentUser.name}`);
            }
        } catch (error: any) {
            alert(error.response?.data?.error || "Ops! Algo deu errado na emissão.");
        }
    };

    return (
        <div className="p-4 lg:p-6 space-y-5">
            {/* ── Page Header ── */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-3">
                <div>
                    <h1 className="text-xl font-black tracking-tight text-[var(--foreground)]">Certificados</h1>
                    <p className="text-xs text-[var(--muted)] font-medium uppercase tracking-wider mt-0.5">
                        Gestão de Pedidos e Emissões
                    </p>
                </div>
                <button
                    onClick={() => setIsJourneyOpen(true)}
                    className="bg-primary text-white px-5 py-2.5 rounded-lg font-bold text-xs flex items-center gap-2 shadow-sm hover:bg-primary/90 transition-all self-start md:self-auto active:scale-95"
                >
                    <Plus size={15} />
                    Novo Pedido
                </button>
            </div>

            {/* ── Main Panel — GitHub-style flat list ── */}
            <div className="rounded-xl border border-slate-200 dark:border-slate-800 overflow-hidden bg-white dark:bg-slate-900 shadow-sm">

                {/* Search + Filters row */}
                <div className="px-4 py-3 border-b border-slate-200 dark:border-slate-800 flex flex-col lg:flex-row gap-3">
                    {/* Search */}
                    <div className="relative flex-1">
                        <Search
                            className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500"
                            size={16}
                        />
                        <input
                            type="text"
                            placeholder="Buscar por titular, CPF/CNPJ ou protocolo..."
                            className="w-full pl-9 pr-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm font-medium focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all placeholder:text-slate-400 dark:placeholder:text-slate-500 shadow-sm text-slate-800 dark:text-slate-100"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>

                    <div className="flex flex-wrap gap-1.5 items-center">
                        <button
                            onClick={() => setShowArchived(!showArchived)}
                            className={cn(
                                "px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border flex items-center gap-2",
                                showArchived
                                    ? "bg-amber-100 text-amber-700 border-amber-200"
                                    : "bg-slate-50 dark:bg-slate-800 text-slate-500 border-slate-200 dark:border-slate-700 hover:bg-slate-100"
                            )}
                        >
                            <Archive size={13} />
                            {showArchived ? "Ocultar Arquivados" : "Exibir Arquivados"}
                        </button>

                        <div className="h-4 w-px bg-slate-200 dark:bg-slate-800 mx-1" />

                        {STATUSES.map((status) => (
                            <button
                                key={status}
                                onClick={() => setStatusFilter(status)}
                                className={cn(
                                    "px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border",
                                    statusFilter === status
                                        ? "bg-primary/10 text-primary border-primary/25 dark:bg-primary/20 dark:border-primary/30"
                                        : "bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-700"
                                )}
                            >
                                {status}
                            </button>
                        ))}
                        <button className="ml-1 px-3 py-1.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-semibold text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 transition-all flex items-center gap-1.5">
                            <Filter size={13} />
                            Filtros
                        </button>
                    </div>
                </div>

                {/* Count bar */}
                <div className="px-4 py-2.5 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 flex items-center justify-between">
                    <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">
                        {filteredCertificates.length} certificado{filteredCertificates.length !== 1 ? "s" : ""}
                    </span>
                    <button className="flex items-center gap-1.5 text-xs font-semibold text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors">
                        <ArrowUpDown size={13} />
                        Última emissão
                    </button>
                </div>

                {/* Rows list */}
                <div className="divide-y divide-slate-100 dark:divide-slate-800">
                    {!certificates && !error && (
                        <div className="px-6 py-10 text-center text-slate-400 dark:text-slate-500 text-xs italic">
                            Carregando certificados...
                        </div>
                    )}
                    {filteredCertificates.length === 0 && certificates && (
                        <div className="px-6 py-10 text-center text-slate-400 dark:text-slate-500 text-xs">
                            Nenhum certificado encontrado.
                        </div>
                    )}
                    {filteredCertificates.map((cert: any) => {
                        const statusCfg = STATUS_CONFIG[cert.status] || STATUS_CONFIG["Pendente"];
                        const StatusIcon = statusCfg.icon;
                        return (
                            <div
                                key={cert.id}
                                onClick={() => {
                                    setSelectedOrder(cert);
                                    setIsDetailsOpen(true);
                                }}
                                className="flex items-center gap-4 px-4 py-3.5 hover:bg-slate-50 dark:hover:bg-slate-800/60 transition-colors group cursor-pointer"
                            >
                                {/* Icon */}
                                <div className="size-9 rounded-lg bg-primary/8 dark:bg-primary/15 flex items-center justify-center text-primary shrink-0">
                                    <User size={16} />
                                </div>

                                {/* Main info */}
                                <div className="flex-1 min-w-0">
                                    <div className="flex flex-wrap items-center gap-2 mb-0.5">
                                        <span className="text-sm font-semibold text-slate-900 dark:text-white truncate">
                                            {cert.holder}
                                        </span>
                                        {/* Category tag */}
                                        <span className="px-2 py-0.5 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-600 rounded-md text-[10px] font-semibold uppercase tracking-wide shrink-0">
                                            {cert.category || "PF"}
                                        </span>
                                    </div>
                                    <p className="text-xs text-slate-500 dark:text-slate-400 truncate">
                                        {cert.doc} · {cert.product} · <span className="font-mono">{cert.protocol}</span>
                                    </p>
                                </div>

                                {/* Right side metadata */}
                                <div className="flex items-center gap-4 shrink-0">
                                    {/* Status badge */}
                                    <span className={cn(
                                        "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold ring-1 ring-inset",
                                        statusCfg.className
                                    )}>
                                        <StatusIcon size={10} />
                                        {statusCfg.label}
                                    </span>

                                    {/* Date */}
                                    <div className="hidden md:flex items-center gap-1.5 text-slate-400 dark:text-slate-500">
                                        <Calendar size={12} />
                                        <span className="text-xs font-medium">{cert.date}</span>
                                    </div>

                                    {/* Actions for Drafts */}
                                    {cert.status === "Rascunho" && (
                                        <div className="flex gap-2 mr-2">
                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    handleResumeDraft(cert);
                                                }}
                                                className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-50 dark:bg-indigo-400/10 text-indigo-700 dark:text-indigo-400 rounded-lg text-xs font-bold hover:bg-indigo-100 transition-all border border-indigo-200 dark:border-indigo-400/20"
                                            >
                                                <FileEdit size={12} />
                                                Continuar
                                            </button>
                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    handleArchive(cert.id);
                                                }}
                                                className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-lg text-xs font-bold hover:bg-slate-100 transition-all border border-slate-200 dark:border-slate-700"
                                                title="Arquivar Rascunho"
                                            >
                                                <Archive size={12} />
                                                Arquivar
                                            </button>
                                        </div>
                                    )}

                                    {cert.status === "Arquivado" && (
                                        <button
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                const restore = async () => {
                                                    const formData = new FormData();
                                                    formData.append('id', cert.id);
                                                    formData.append('status', 'Rascunho');
                                                    formData.append('isUpdateStatusOnly', 'true');
                                                    await axios.post('/api/integracao/vendas', formData);
                                                    mutate(`/api/certificates?seller=${currentUser.role === "admin" ? "admin" : currentUser.name}`);
                                                };
                                                restore();
                                            }}
                                            className="mr-2 flex items-center gap-1.5 px-3 py-1.5 bg-emerald-50 dark:bg-emerald-400/10 text-emerald-700 dark:text-emerald-400 rounded-lg text-xs font-bold hover:bg-emerald-100 transition-all border border-emerald-200 dark:border-emerald-400/20"
                                        >
                                            <CheckCircle2 size={12} />
                                            Desarquivar
                                        </button>
                                    )}

                                    {/* More */}
                                    <button className="p-1.5 rounded-md text-slate-300 dark:text-slate-600 opacity-0 group-hover:opacity-100 hover:bg-slate-100 dark:hover:bg-slate-700 hover:text-slate-600 dark:hover:text-slate-300 transition-all">
                                        <MoreHorizontal size={16} />
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* Footer */}
                <div className="px-4 py-3 bg-slate-50 dark:bg-slate-800/50 border-t border-slate-200 dark:border-slate-800 flex items-center justify-between">
                    <p className="text-[10px] text-slate-500 dark:text-slate-400 font-semibold uppercase tracking-wider">
                        Mostrando {filteredCertificates.length} resultado{filteredCertificates.length !== 1 ? "s" : ""}
                    </p>
                    <div className="flex gap-1">
                        <button className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 text-xs font-semibold text-slate-400 disabled:opacity-40 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors" disabled>
                            Anterior
                        </button>
                        <button className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-xs font-semibold text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                            Próxima
                        </button>
                    </div>
                </div>
            </div>

            <OrderDetailsModal
                isOpen={isDetailsOpen}
                onClose={() => setIsDetailsOpen(false)}
                order={selectedOrder}
            />

            <OrderJourneyModal
                isOpen={isJourneyOpen}
                onClose={() => {
                    setIsJourneyOpen(false);
                    setSelectedOrder(null);
                }}
                onSubmit={handleOrderSubmit}
                products={products || []}
                editingOrder={selectedOrder}
            />
        </div>
    );
}
