"use client";

import { cn } from "@/lib/utils";
import { forwardRef, InputHTMLAttributes } from "react";

interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
    label: string;
    error?: string;
    helpText?: string;
}

const Input = forwardRef<HTMLInputElement, InputProps>(
    ({ label, error, helpText, className, ...props }, ref) => {
        return (
            <div className="space-y-2 flex flex-col group">
                <label className="text-[12px] font-bold text-[var(--foreground)]/80 px-1 mb-1">
                    {label}
                </label>
                <div className="relative">
                    <input
                        ref={ref}
                        className={cn(
                            "w-full px-4 py-3 bg-[var(--accent)]/50 border border-[var(--border)] rounded-xl text-[13px] font-medium transition-all duration-200",
                            "placeholder:text-[var(--muted)]/40 focus:outline-none focus:border-primary focus:ring-4 focus:ring-primary/10 focus:bg-[var(--card)]",
                            "hover:border-[var(--muted)] shadow-sm dark:shadow-none",
                            error && "border-rose-500 focus:border-rose-500 focus:ring-rose-500/10",
                            className
                        )}
                        {...props}
                    />
                </div>
                {error ? (
                    <p className="text-[10px] font-black text-error px-1 uppercase tracking-tight">
                        {error}
                    </p>
                ) : helpText && (
                    <p className="text-[11px] font-medium text-on-surface-variant/60 px-1 leading-tight italic">
                        {helpText}
                    </p>
                )}
            </div>
        );
    }
);

Input.displayName = "Input";

export default Input;
